            /** Format: int64 */
            bad_us: number;
            /** Format: int64 */
            unknown_us: number;
            /** Format: int64 */
            excluded_us: number;
            /** Format: int64 */
            healthy_us: number;
            /** Format: int64 */
            degraded_us: number;
            /** Format: int64 */
            down_us: number;
            /** Format: int64 */
